interface SlashCommandState {
  imageAltText: string;
  imageFileName: string;
  imageFileSrc: string | null;
  imageUrl: string;
  isImageDialogOpen: boolean;
  isLayoutPresetOpen: boolean;
  isOpen: boolean;
  isYouTubeDialogOpen: boolean;
  pendingImageTargetKey: string | null;
  pendingLayoutTargetKey: string | null;
  pendingYouTubeTargetKey: string | null;
  query: string;
  rawSelectedCommandId: SlashCommandSelection;
  youTubeUrl: string;
}

type SlashCommandAction =
  | { type: "patch"; payload: Partial<SlashCommandState> }
  | {
      type: "move-selected-command";
      payload: {
        commands: SlashCommand[];
        direction: "down" | "up";
      };
    }
  | {
      type: "set-image-file";
      payload: {
        fileName: string;
        src: string;
      };
    };

const createInitialSlashCommandState = (
  rawSelectedCommandId: SlashCommandSelection
): SlashCommandState => ({
  imageAltText: "",
  imageFileName: "",
  imageFileSrc: null,
  imageUrl: "",
  isImageDialogOpen: false,
  isLayoutPresetOpen: false,
  isOpen: false,
  isYouTubeDialogOpen: false,
  pendingImageTargetKey: null,
  pendingLayoutTargetKey: null,
  pendingYouTubeTargetKey: null,
  query: "",
  rawSelectedCommandId,
  youTubeUrl: "",
});

const applySlashCommandPatch = (
  state: SlashCommandState,
  patch: Partial<SlashCommandState>
): SlashCommandState => {
  for (const key of Object.keys(patch) as Array<keyof SlashCommandState>) {
    if (state[key] !== patch[key]) {
      return { ...state, ...patch };
    }
  }

  return state;
};

const slashCommandReducer = (
  state: SlashCommandState,
  action: SlashCommandAction
): SlashCommandState => {
  switch (action.type) {
    case "patch": {
      return applySlashCommandPatch(state, action.payload);
    }
    case "move-selected-command": {
      return applySlashCommandPatch(state, {
        rawSelectedCommandId: getNeighborCommandId(
          action.payload.commands,
          state.rawSelectedCommandId,
          action.payload.direction
        ),
      });
    }
    case "set-image-file": {
      return applySlashCommandPatch(state, {
        imageAltText: state.imageAltText || action.payload.fileName,
        imageFileName: action.payload.fileName,
        imageFileSrc: action.payload.src,
        imageUrl: "",
      });
    }
    default: {
      return state;
    }
  }
};

export function SlashCommandPlugin({ features }: SlashCommandPluginProps) {
  const [editor] = useLexicalComposerContext();
  const availableCommands = useMemo(() => {
    return getEnabledSlashCommands(features);
  }, [features]);
  const [state, dispatch] = useReducer(
    slashCommandReducer,
    getFirstCommandId(availableCommands),
    createInitialSlashCommandState
  );
  const {
    imageAltText,
    imageFileName,
    imageFileSrc,
    imageUrl,
    isImageDialogOpen,
    isLayoutPresetOpen,
    isOpen,
    isYouTubeDialogOpen,
    pendingImageTargetKey,
    pendingLayoutTargetKey,
    pendingYouTubeTargetKey,
    query,
    rawSelectedCommandId,
    youTubeUrl,
  } = state;
  const commandListRef = useRef<HTMLDivElement | null>(null);
  const animationFrameRef = useRef<number | null>(null);

  const filteredCommands = useMemo(() => {
    return filterSlashCommands(availableCommands, query);
  }, [availableCommands, query]);

  const selectedCommandId = useMemo<SlashCommandId | "">(() => {
    if (filteredCommands.length === 0) {
      return "";
    }

    return hasSelectedCommand(filteredCommands, rawSelectedCommandId)
      ? rawSelectedCommandId
      : getFirstCommandId(filteredCommands);
  }, [filteredCommands, rawSelectedCommandId]);

  const selectedIndex = useMemo(() => {
    return getSelectedCommandIndex(filteredCommands, selectedCommandId);
  }, [filteredCommands, selectedCommandId]);

  const anchor = useMemo(() => {
    return createSlashMenuAnchor(editor);
  }, [editor]);

  const updateSlashMenu = useCallback(() => {
    const selection = $getSelection();
    const isCollapsedRangeSelection =
      $isRangeSelection(selection) && selection.isCollapsed();

    if (!isCollapsedRangeSelection) {
      dispatch({
        type: "patch",
        payload: { isLayoutPresetOpen: false, isOpen: false },
      });
      return;
    }

    const node = selection.anchor.getNode();
    if (!$isTextNode(node)) {
      dispatch({
        type: "patch",
        payload: { isLayoutPresetOpen: false, isOpen: false },
      });
      return;
    }

    const textUpToCursor = node
      .getTextContent()
      .slice(0, selection.anchor.offset);
    const nextQuery = getSlashQueryMatch(textUpToCursor);

    if (nextQuery === null) {
      dispatch({
        type: "patch",
        payload: { isLayoutPresetOpen: false, isOpen: false },
      });
      return;
    }

    if (!getSelectionRectangle(editor)) {
      dispatch({ type: "patch", payload: { isOpen: false } });
      return;
    }

    dispatch({
      type: "patch",
      payload: { isOpen: true, query: nextQuery },
    });
  }, [editor]);

  const scheduleSlashMenuUpdate = useCallback(() => {
    if (animationFrameRef.current !== null) {
      return;
    }

    animationFrameRef.current = window.requestAnimationFrame(() => {
      animationFrameRef.current = null;
      editor.getEditorState().read(() => {
        updateSlashMenu();
      });
    });
  }, [editor, updateSlashMenu]);

  const resetImageDialog = useCallback(() => {
    dispatch({
      type: "patch",
      payload: {
        imageAltText: "",
        imageFileName: "",
        imageFileSrc: null,
        imageUrl: "",
        isImageDialogOpen: false,
        pendingImageTargetKey: null,
      },
    });
  }, []);

  const resetYouTubeDialog = useCallback(() => {
    dispatch({
      type: "patch",
      payload: {
        isYouTubeDialogOpen: false,
        pendingYouTubeTargetKey: null,
        youTubeUrl: "",
      },
    });
  }, []);

  const handleImageFileChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      event.target.value = "";

      if (!file) {
        dispatch({
          type: "patch",
          payload: { imageFileName: "", imageFileSrc: null },
        });
        return;
      }

      readFileAsDataUrl(file)
        .then((src) => {
          dispatch({
            type: "set-image-file",
            payload: { fileName: file.name, src },
          });
        })
        .catch(() => {
          dispatch({
            type: "patch",
            payload: { imageFileName: "", imageFileSrc: null },
          });
        });
    },
    []
  );

  const executeCommand = useCallback(
    (commandId: SlashCommandId) => {
      if (
        commandId === "columns" ||
        commandId === "image" ||
        commandId === "youtube"
      ) {
        let targetNodeKey: string | null = null;

        editor.getEditorState().read(() => {
          const selection = $getSelection();
          if (!$isRangeSelection(selection)) {
            return;
          }

          const node = selection.anchor.getNode();
          if (!$isTextNode(node)) {
            return;
          }

          targetNodeKey = node.getTopLevelElementOrThrow().getKey();
        });

        if (commandId === "columns") {
          dispatch({
            type: "patch",
            payload: {
              isLayoutPresetOpen: true,
              isOpen: false,
              pendingLayoutTargetKey: targetNodeKey,
            },
          });
        } else if (commandId === "youtube") {
          dispatch({
            type: "patch",
            payload: {
              isOpen: false,
              isYouTubeDialogOpen: true,
              pendingYouTubeTargetKey: targetNodeKey,
            },
          });
        } else {
          dispatch({
            type: "patch",
            payload: {
              isImageDialogOpen: true,
              isOpen: false,
              pendingImageTargetKey: targetNodeKey,
            },
          });
        }
        return;
      }

      editor.update(() => {
        const selection = $getSelection();
        if (!$isRangeSelection(selection)) {
          return;
        }

        const node = selection.anchor.getNode();
        if (!$isTextNode(node)) {
          return;
        }

        node.setTextContent("");

        const element = node.getTopLevelElementOrThrow();
        SLASH_COMMAND_EXECUTORS[commandId](element);
      });

      dispatch({ type: "patch", payload: { isOpen: false } });
    },
    [editor]
  );

  const executeLayoutPreset = useCallback(
    (templateColumns: string) => {
      if (!pendingLayoutTargetKey) {
        return;
      }

      editor.dispatchCommand(INSERT_LAYOUT_COMMAND, {
        targetNodeKey: pendingLayoutTargetKey,
        templateColumns,
      });

      dispatch({
        type: "patch",
        payload: {
          isLayoutPresetOpen: false,
          isOpen: false,
          pendingLayoutTargetKey: null,
        },
      });
    },
    [editor, pendingLayoutTargetKey]
  );

  const submitImage = useCallback(() => {
    const nextImageSrc = imageFileSrc ?? imageUrl.trim();
    if (!(nextImageSrc && pendingImageTargetKey)) {
      return;
    }

    editor.dispatchCommand(INSERT_IMAGE_COMMAND, {
      altText: imageAltText.trim(),
      src: nextImageSrc,
      targetNodeKey: pendingImageTargetKey,
    });

    dispatch({
      type: "patch",
      payload: {
        imageAltText: "",
        imageFileName: "",
        imageFileSrc: null,
        imageUrl: "",
        isImageDialogOpen: false,
        isOpen: false,
        pendingImageTargetKey: null,
      },
    });
  }, [editor, imageAltText, imageFileSrc, imageUrl, pendingImageTargetKey]);

  const submitYouTube = useCallback(() => {
    if (!pendingYouTubeTargetKey) {
      return;
    }

    const videoId = parseYouTubeUrl(youTubeUrl);
    if (!videoId) {
      return;
    }

    editor.dispatchCommand(INSERT_YOUTUBE_COMMAND, {
      targetNodeKey: pendingYouTubeTargetKey,
      videoId,
    });

    dispatch({
      type: "patch",
      payload: {
        isOpen: false,
        isYouTubeDialogOpen: false,
        pendingYouTubeTargetKey: null,
        youTubeUrl: "",
      },
    });
  }, [editor, pendingYouTubeTargetKey, youTubeUrl]);

  useEffect(() => {
    if (
      !(isOpen && selectedCommandId) ||
      isImageDialogOpen ||
      isLayoutPresetOpen ||
      isYouTubeDialogOpen
    ) {
      return;
    }

    const animationFrameId = window.requestAnimationFrame(() => {
      const selectedItemSelector = `[cmdk-item=""][data-value="${window.CSS.escape(selectedCommandId)}"]`;
      const selectedItem =
        commandListRef.current?.querySelector<HTMLElement>(
          selectedItemSelector
        );

      selectedItem?.scrollIntoView({ block: "nearest" });
    });

    return () => {
      window.cancelAnimationFrame(animationFrameId);
    };
  }, [
    isImageDialogOpen,
    isLayoutPresetOpen,
    isOpen,
    isYouTubeDialogOpen,
    selectedCommandId,
  ]);

  useEffect(() => {
    if (isImageDialogOpen || isLayoutPresetOpen || isYouTubeDialogOpen) {
      return;
    }

    return editor.registerUpdateListener(() => {
      scheduleSlashMenuUpdate();
    });
  }, [
    editor,
    isImageDialogOpen,
    isLayoutPresetOpen,
    isYouTubeDialogOpen,
    scheduleSlashMenuUpdate,
  ]);

  useEffect(() => {
    return () => {
      if (animationFrameRef.current !== null) {
        window.cancelAnimationFrame(animationFrameRef.current);
      }
      animationFrameRef.current = null;
    };
  }, []);

  const handleImageUrlInputRef = useCallback(
    (element: HTMLInputElement | null) => {
      if (!(element && isImageDialogOpen)) {
        return;
      }

      element.focus();
    },
    [isImageDialogOpen]
  );

  const handleYouTubeUrlInputRef = useCallback(
    (element: HTMLInputElement | null) => {
      if (!(element && isYouTubeDialogOpen)) {
        return;
      }

      element.focus();
    },
    [isYouTubeDialogOpen]
  );

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    return mergeRegister(
      editor.registerCommand(
        KEY_ARROW_DOWN_COMMAND,
        (event) => {
          if (isImageDialogOpen || isLayoutPresetOpen || isYouTubeDialogOpen) {
            return true;
          }

          event.preventDefault();
          dispatch({
            type: "move-selected-command",
            payload: { commands: filteredCommands, direction: "down" },
          });
          return true;
        },
        COMMAND_PRIORITY_HIGH
      ),
      editor.registerCommand(
        KEY_ARROW_UP_COMMAND,
        (event) => {
          if (isImageDialogOpen || isLayoutPresetOpen || isYouTubeDialogOpen) {
            return true;
          }

          event.preventDefault();
          dispatch({
            type: "move-selected-command",
            payload: { commands: filteredCommands, direction: "up" },
          });
          return true;
        },
        COMMAND_PRIORITY_HIGH
      ),
      editor.registerCommand(
        KEY_ENTER_COMMAND,
        (event) => {
          event?.preventDefault();

          if (isLayoutPresetOpen) {
            executeLayoutPreset("1fr 1fr");
            return true;
          }

          if (isImageDialogOpen) {
            submitImage();
            return true;
          }

          if (isYouTubeDialogOpen) {
            submitYouTube();
            return true;
          }

          const selectedCommand = filteredCommands[selectedIndex];
          if (selectedCommand) {
            executeCommand(selectedCommand.id);
          }
          return true;
        },
        COMMAND_PRIORITY_HIGH
      ),
      editor.registerCommand(
        KEY_ESCAPE_COMMAND,
        () => {
          if (isImageDialogOpen) {
            resetImageDialog();
            return true;
          }

          if (isLayoutPresetOpen) {
            dispatch({
              type: "patch",
              payload: {
                isLayoutPresetOpen: false,
                pendingLayoutTargetKey: null,
              },
            });
            return true;
          }

          if (isYouTubeDialogOpen) {
            resetYouTubeDialog();
            return true;
          }

          dispatch({ type: "patch", payload: { isOpen: false } });
          return true;
        },
        COMMAND_PRIORITY_HIGH
      )
    );
  }, [
    editor,
    executeCommand,
    executeLayoutPreset,
    filteredCommands,
    isImageDialogOpen,
    isLayoutPresetOpen,
    isOpen,
    isYouTubeDialogOpen,
    resetYouTubeDialog,
    resetImageDialog,
    selectedIndex,
    submitImage,
    submitYouTube,
  ]);

  return (
    <>
      <PopoverPrimitive.Root
        modal={false}
        open={isOpen && filteredCommands.length > 0}
      >
        <PopoverPrimitive.Portal>
          <PopoverPrimitive.Positioner
            align="start"
            anchor={anchor}
            className="isolate z-50"
            collisionAvoidance={SLASH_MENU_COLLISION_AVOIDANCE}
            positionMethod="fixed"
            side="bottom"
            sideOffset={4}
          >
            <PopoverPrimitive.Popup
              className={cn(
                "data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:fade-in-0 data-open:zoom-in-95 data-closed:fade-out-0 data-closed:zoom-out-95 z-50 flex w-72 origin-(--transform-origin) flex-col overflow-hidden rounded-lg bg-popover p-0 text-popover-foreground text-sm shadow-md outline-hidden ring-1 ring-foreground/10 duration-100 data-closed:animate-out data-open:animate-in"
              )}
              data-slot="slash-command-popover"
              finalFocus={false}
              initialFocus={false}
            >
              <Command
                onValueChange={(value) =>
                  dispatch({
                    type: "patch",
                    payload: { rawSelectedCommandId: value as SlashCommandId },
                  })
                }
                shouldFilter={false}
                value={selectedCommandId}
              >
                <CommandList ref={commandListRef}>
                  <CommandGroup heading="Blocks">
                    {filteredCommands.map((command, index) => (
                      <CommandItem
                        className={
                          index === selectedIndex
                            ? "bg-muted text-foreground"
                            : ""
                        }
                        key={command.id}
                        onMouseEnter={() =>
                          dispatch({
                            type: "patch",
                            payload: { rawSelectedCommandId: command.id },
                          })
                        }
                        onSelect={() => executeCommand(command.id)}
                        value={command.id}
                      >
                        <command.icon className="size-4 shrink-0 text-muted-foreground" />
                        <div className="flex flex-col">
                          <span className="text-sm">{command.label}</span>
                          <span className="text-muted-foreground text-xs">
                            {command.description}
                          </span>
                        </div>
                      </CommandItem>
                    ))}
                  </CommandGroup>
                  {filteredCommands.length === 0 ? (
                    <CommandEmpty>No results found</CommandEmpty>
                  ) : null}
                </CommandList>
              </Command>
            </PopoverPrimitive.Popup>
          </PopoverPrimitive.Positioner>
        </PopoverPrimitive.Portal>
      </PopoverPrimitive.Root>

      <SlashLayoutDialog
        onCancel={() => {
          dispatch({
            type: "patch",
            payload: {
              isLayoutPresetOpen: false,
              pendingLayoutTargetKey: null,
            },
          });
        }}
        onOpenChange={(open) =>
          dispatch({
            type: "patch",
            payload: open
              ? { isLayoutPresetOpen: true }
              : { isLayoutPresetOpen: false, pendingLayoutTargetKey: null },
          })
        }
        onSelectPreset={executeLayoutPreset}
        open={isLayoutPresetOpen}
      />

      <Dialog
        onOpenChange={(open) => {
          if (!open) {
            resetImageDialog();
          }
        }}
        open={isImageDialogOpen}
      >
        <DialogContent className="sm:max-w-lg" showCloseButton>
          <DialogHeader>
            <DialogTitle>Insert image</DialogTitle>
            <DialogDescription>
              Add an external image URL and optional alt text.
            </DialogDescription>
          </DialogHeader>

          <form
            className="space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              submitImage();
            }}
          >
            <div className="grid gap-2">
              <label className="font-medium text-sm" htmlFor="slash-image-url">
                Image URL
              </label>
              <Input
                id="slash-image-url"
                onChange={(event) =>
                  dispatch({
                    type: "patch",
                    payload: { imageUrl: event.target.value },
                  })
                }
                placeholder="https://example.com/image.jpg"
                ref={handleImageUrlInputRef}
                type="url"
                value={imageUrl}
              />
            </div>

            <div className="grid gap-2">
              <label className="font-medium text-sm" htmlFor="slash-image-file">
                Local file
              </label>
              <Input
                accept="image/*"
                id="slash-image-file"
                onChange={handleImageFileChange}
                type="file"
              />
              {imageFileName ? (
                <p className="text-muted-foreground text-xs">
                  Selected: {imageFileName}
                </p>
              ) : null}
            </div>

            <div className="grid gap-2">
              <label className="font-medium text-sm" htmlFor="slash-image-alt">
                Alt text
              </label>
              <Textarea
                id="slash-image-alt"
                onChange={(event) =>
                  dispatch({
                    type: "patch",
                    payload: { imageAltText: event.target.value },
                  })
                }
                placeholder="Describe the image for accessibility"
                rows={3}
                value={imageAltText}
              />
            </div>

            <DialogFooter showCloseButton={false}>
              <Button
                onClick={resetImageDialog}
                type="button"
                variant="outline"
              >
                Cancel
              </Button>
              <Button
                disabled={!(imageFileSrc || imageUrl.trim())}
                type="submit"
              >
                Insert image
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <Dialog
        onOpenChange={(open) => {
          if (!open) {
            resetYouTubeDialog();
          }
        }}
        open={isYouTubeDialogOpen}
      >
        <DialogContent className="sm:max-w-lg" showCloseButton>
          <DialogHeader>
            <DialogTitle>Embed YouTube video</DialogTitle>
            <DialogDescription>
              Paste a YouTube URL and it will be embedded as a video block.
            </DialogDescription>
          </DialogHeader>

          <form
            className="space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              submitYouTube();
            }}
          >
            <div className="grid gap-2">
              <label
                className="font-medium text-sm"
                htmlFor="slash-youtube-url"
              >
                YouTube URL
              </label>
              <Input
                id="slash-youtube-url"
                onChange={(event) =>
                  dispatch({
                    type: "patch",
                    payload: { youTubeUrl: event.target.value },
                  })
                }
                placeholder="https://www.youtube.com/watch?v=jNQXAC9IVRw"
                ref={handleYouTubeUrlInputRef}
                type="url"
                value={youTubeUrl}
              />
              <p className="text-muted-foreground text-xs">
                Supports `youtube.com`, `youtu.be`, and embed links.
              </p>
            </div>

            <DialogFooter showCloseButton={false}>
              <Button
                onClick={resetYouTubeDialog}
                type="button"
                variant="outline"
              >
                Cancel
              </Button>
              <Button disabled={!parseYouTubeUrl(youTubeUrl)} type="submit">
                Embed video
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
}

import type { LucideIcon } from "lucide-react";
import type { EditorFeatureFlags } from "../../core/types";

export type SlashCommandFeatureFlag = keyof Pick<
  EditorFeatureFlags,
  "collapsible" | "images" | "layouts" | "math" | "tables" | "youtube"
>;

export type SlashCommandId =
  | "paragraph"
  | "h1"
  | "h2"
  | "h3"
  | "quote"
  | "code"
  | "bullet"
  | "number"
  | "check"
  | "math"
  | "image"
  | "youtube"
  | "collapsible"
  | "columns"
  | "table"
  | "hr";

export type SlashCommandSelection = SlashCommandId | "";

export interface SlashCommand {
  description: string;
  icon: LucideIcon;
  id: SlashCommandId;
  keywords: string[];
  label: string;
  requiredFeature?: SlashCommandFeatureFlag;
}

export interface SlashMenuPosition {
  left: number;
  top: number;
}

export interface SlashMenuAnchor {
  getBoundingClientRect: () => DOMRect;
  getClientRects: () => DOMRectList;
}

import type { SlashCommand, SlashCommandSelection } from "./types";

export const SLASH_QUERY_PATTERN = /^\/(\w*)$/;

export const filterSlashCommands = (
  commands: SlashCommand[],
  query: string
): SlashCommand[] => {
  if (!query) {
    return commands;
  }

  const normalizedQuery = query.toLowerCase();

  return commands.filter((command) => {
    return (
      command.label.toLowerCase().includes(normalizedQuery) ||
      command.keywords.some((keyword) => keyword.includes(normalizedQuery))
    );
  });
};

export const getFirstCommandId = (
  commands: SlashCommand[]
): SlashCommandSelection => {
  return commands[0]?.id ?? "";
};

export const getSelectedCommandIndex = (
  commands: SlashCommand[],
  selectedCommandId: SlashCommandSelection
): number => {
  return commands.findIndex((command) => command.id === selectedCommandId);
};

export const getNeighborCommandId = (
  commands: SlashCommand[],
  selectedCommandId: SlashCommandSelection,
  direction: "down" | "up"
): SlashCommandSelection => {
  const currentIndex = getSelectedCommandIndex(commands, selectedCommandId);

  if (currentIndex < 0) {
    return getFirstCommandId(commands);
  }

  const nextIndex =
    direction === "down"
      ? Math.min(currentIndex + 1, commands.length - 1)
      : Math.max(currentIndex - 1, 0);

  return commands[nextIndex]?.id ?? selectedCommandId;
};

export const hasSelectedCommand = (
  commands: SlashCommand[],
  selectedCommandId: SlashCommandSelection
): boolean => {
  return commands.some((command) => command.id === selectedCommandId);
};

export const getSlashQueryMatch = (textUpToCursor: string): string | null => {
  const match = textUpToCursor.match(SLASH_QUERY_PATTERN);

  return match?.[1] ?? null;
};

import {
  $deleteTableColumnAtSelection,
  $deleteTableRowAtSelection,
  $getTableCellNodeFromLexicalNode,
  $getTableNodeFromLexicalNodeOrThrow,
  $insertTableColumnAtSelection,
  $insertTableRowAtSelection,
  $isTableSelection,
} from "@lexical/table";
import { $getSelection, $isRangeSelection, type LexicalEditor } from "lexical";

export const insertTableRow = (editor: LexicalEditor, insertAfter: boolean) => {
  editor.update(() => {
    $insertTableRowAtSelection(insertAfter);
  });
};

export const insertTableRows = (
  editor: LexicalEditor,
  insertAfter: boolean,
  count: number
) => {
  editor.update(() => {
    for (let index = 0; index < count; index += 1) {
      $insertTableRowAtSelection(insertAfter);
    }
  });
};

export const insertTableColumn = (
  editor: LexicalEditor,
  insertAfter: boolean
) => {
  editor.update(() => {
    $insertTableColumnAtSelection(insertAfter);
  });
};

export const insertTableColumns = (
  editor: LexicalEditor,
  insertAfter: boolean,
  count: number
) => {
  editor.update(() => {
    for (let index = 0; index < count; index += 1) {
      $insertTableColumnAtSelection(insertAfter);
    }
  });
};

export const deleteSelectedTableRow = (editor: LexicalEditor) => {
  editor.update(() => {
    $deleteTableRowAtSelection();
  });
};

export const deleteSelectedTableColumn = (editor: LexicalEditor) => {
  editor.update(() => {
    $deleteTableColumnAtSelection();
  });
};

export const deleteSelectedTable = (editor: LexicalEditor) => {
  editor.update(() => {
    const selection = $getSelection();
    if (!($isRangeSelection(selection) || $isTableSelection(selection))) {
      return;
    }

    const tableCellNode = $getTableCellNodeFromLexicalNode(
      selection.anchor.getNode()
    );
    if (!tableCellNode) {
      return;
    }

    $getTableNodeFromLexicalNodeOrThrow(tableCellNode).remove();
  });
};

