            onClick={() => onHeadingClick(key)}
            type="button"
          >
            <span
              className={cn(
                "h-[2.5px] rounded-full transition-all duration-200 ease-out",
                widthClass,
                isActive
                  ? "scale-x-110 bg-primary shadow-xs"
